func (os StatSlice) Definition(mods ...bob.Mod[*dialect.SelectQuery]) DefinitionsQuery {
	pkDefinitionID := make(pgtypes.Array[int64], 0, len(os))

	// the array is only a filter (semi-join), so duplicate keys can be
	// dropped before they are sent over the wire
	seenDefinitionID := make(map[int64]struct{}, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		if _, ok := seenDefinitionID[o.DefinitionID]; ok {
			continue
		}
		seenDefinitionID[o.DefinitionID] = struct{}{}
		pkDefinitionID = append(pkDefinitionID, o.DefinitionID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkDefinitionID), "bigint[]"))

	return Definitions.Query(append(mods,
		sm.Where(Definitions.Columns.ID.EQ(PKArgExpr)),
	)...)
}

