type statWhere[Q psql.Filterable] struct {
	cols           statColumns
	ID             psql.WhereMod[Q, int64]
	DefinitionID   psql.WhereMod[Q, int64]
	Scope          psql.WhereMod[Q, enums.StatScope]
	Key            psql.WhereMod[Q, string]
	Name           psql.WhereNullMod[Q, string]
	ValueType      psql.WhereMod[Q, enums.StatValueType]
	HigherIsBetter psql.WhereNullMod[Q, bool]
	Unit           psql.WhereMod[Q, string]
	Display        psql.WhereMod[Q, bool]
	IsRecord       psql.WhereMod[Q, bool]
	CreatedAt      psql.WhereMod[Q, time.Time]
	UpdatedAt      psql.WhereMod[Q, time.Time]
	R              statWhereR[Q]
}

func (statWhere[Q]) AliasedAs(alias string) statWhere[Q] {
	return buildStatWhere[Q](buildStatColumns(alias))
}

func buildStatWhere[Q psql.Filterable](cols statColumns) statWhere[Q] {
	return statWhere[Q]{
		cols:           cols,
		ID:             psql.Where[Q, int64](cols.ID.Expression),
		DefinitionID:   psql.Where[Q, int64](cols.DefinitionID.Expression),
		Scope:          psql.Where[Q, enums.StatScope](cols.Scope.Expression),
		Key:            psql.Where[Q, string](cols.Key.Expression),
		Name:           psql.WhereNull[Q, string](cols.Name.Expression),
		ValueType:      psql.Where[Q, enums.StatValueType](cols.ValueType.Expression),
		HigherIsBetter: psql.WhereNull[Q, bool](cols.HigherIsBetter.Expression),
		Unit:           psql.Where[Q, string](cols.Unit.Expression),
		Display:        psql.Where[Q, bool](cols.Display.Expression),
		IsRecord:       psql.Where[Q, bool](cols.IsRecord.Expression),
		CreatedAt:      psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:      psql.Where[Q, time.Time](cols.UpdatedAt.Expression),
		R:              statWhereR[Q]{cols: cols},
	}
}

// statWhereR holds the relationship-based filters of
// statWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type statWhereR[Q psql.Filterable] struct {
	cols statColumns
}

// HasStatRecords filters parents that have a matching StatRecords using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to StatRecords).
func (w statWhereR[Q]) HasStatRecords(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(StatRecords.NameExpr()),
		sm.Where(StatRecords.Columns.StatID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasStatValues filters parents that have a matching StatValues using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to StatValues).
func (w statWhereR[Q]) HasStatValues(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(StatValues.NameExpr()),
		sm.Where(StatValues.Columns.StatID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasDefinition filters parents that have a matching Definition using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Definitions).
func (w statWhereR[Q]) HasDefinition(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Definitions.NameExpr()),
		sm.Where(Definitions.Columns.ID.EQ(w.cols.DefinitionID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasDefinitionVersions filters parents that have a matching DefinitionVersions (a
// many-to-many relationship) using a correlated EXISTS subquery instead of
// INNER JOINs, so the parent rows are not multiplied. The optional filters are
// applied to the subquery (i.e. to DefinitionVersions).
func (w statWhereR[Q]) HasDefinitionVersions(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(DefinitionVersionStats.NameExpr()),
		sm.InnerJoin(DefinitionVersions.NameExpr()).On(
			DefinitionVersions.Columns.ID.EQ(DefinitionVersionStats.Columns.DefinitionVersionID),
		),
		sm.Where(DefinitionVersionStats.Columns.StatID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// NULL-tolerant scan buffer for statScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type statPreloadBuf struct {
	ID             null.Val[int64]
	DefinitionID   null.Val[int64]
	Scope          null.Val[enums.StatScope]
	Key            null.Val[string]
	Name           null.Val[string]
	ValueType      null.Val[enums.StatValueType]
	HigherIsBetter null.Val[bool]
	Unit           null.Val[string]
	Display        null.Val[bool]
	IsRecord       null.Val[bool]
	CreatedAt      null.Val[time.Time]
	UpdatedAt      null.Val[time.Time]
}

// statScanMapperNullable maps the preloaded stat
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func statScanMapperNullable(prefix string) scan.Mapper[*Stat] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Stat, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *statPreloadBuf) any
		}
		targets := make([]target, 0, 12)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *statPreloadBuf) any { return &b.ID }})
			case "definition_id":
				targets = append(targets, target{i, func(b *statPreloadBuf) any { return &b.DefinitionID }})
			case "scope":
				targets = append(targets, target{i, func(b *statPreloadBuf) any { return &b.Scope }})
			case "key":
				targets = append(targets, target{i, func(b *statPreloadBuf) any { return &b.Key }})
			case "name":
				targets = append(targets, target{i, func(b *statPreloadBuf) any { return &b.Name }})
			case "value_type":
				targets = append(targets, target{i, func(b *statPreloadBuf) any { return &b.ValueType }})
			case "higher_is_better":
				targets = append(targets, target{i, func(b *statPreloadBuf) any { return &b.HigherIsBetter }})
			case "unit":
				targets = append(targets, target{i, func(b *statPreloadBuf) any { return &b.Unit }})
			case "display":
				targets = append(targets, target{i, func(b *statPreloadBuf) any { return &b.Display }})
			case "is_record":
				targets = append(targets, target{i, func(b *statPreloadBuf) any { return &b.IsRecord }})
			case "created_at":
				targets = append(targets, target{i, func(b *statPreloadBuf) any { return &b.CreatedAt }})
			case "updated_at":
				targets = append(targets, target{i, func(b *statPreloadBuf) any { return &b.UpdatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(statPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Stat, error) {
				buf := link.(*statPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.DefinitionID.IsValue()) &&
					!(buf.Scope.IsValue()) &&
					!(buf.Key.IsValue()) &&
					!(buf.Name.IsValue()) &&
					!(buf.ValueType.IsValue()) &&
					!(buf.HigherIsBetter.IsValue()) &&
					!(buf.Unit.IsValue()) &&
					!(buf.Display.IsValue()) &&
					!(buf.IsRecord.IsValue()) &&
					!(buf.CreatedAt.IsValue()) &&
					!(buf.UpdatedAt.IsValue()) {
					return nil, nil
				}

				o := new(Stat)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.DefinitionID.IsValue() {
					o.DefinitionID = buf.DefinitionID.MustGet()
				}
				if buf.Scope.IsValue() {
					o.Scope = buf.Scope.MustGet()
				}
				if buf.Key.IsValue() {
					o.Key = buf.Key.MustGet()
				}
				o.Name = buf.Name
				if buf.ValueType.IsValue() {
					o.ValueType = buf.ValueType.MustGet()
				}
				o.HigherIsBetter = buf.HigherIsBetter
				if buf.Unit.IsValue() {
					o.Unit = buf.Unit.MustGet()
				}
				if buf.Display.IsValue() {
					o.Display = buf.Display.MustGet()
				}
				if buf.IsRecord.IsValue() {
					o.IsRecord = buf.IsRecord.MustGet()
				}
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				if buf.UpdatedAt.IsValue() {
					o.UpdatedAt = buf.UpdatedAt.MustGet()
				}
				return o, nil
			}
	}
}

func (o *Stat) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "DefinitionVersions":
		rels, ok := retrieved.(DefinitionVersionSlice)
		if !ok {
			return fmt.Errorf("stat cannot load %T as %q", retrieved, name)
		}

		o.R.DefinitionVersions = rels
		o.R.Loaded.DefinitionVersions = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Stats = StatSlice{o}
			}
		}
		return nil
	case "StatRecords":
		rels, ok := retrieved.(StatRecordSlice)
		if !ok {
			return fmt.Errorf("stat cannot load %T as %q", retrieved, name)
		}

		o.R.StatRecords = rels
		o.R.Loaded.StatRecords = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Stat = o
				rel.R.Loaded.Stat = true
			}
		}
		return nil
	case "StatValues":
		rels, ok := retrieved.(StatValueSlice)
		if !ok {
			return fmt.Errorf("stat cannot load %T as %q", retrieved, name)
		}

		o.R.StatValues = rels
		o.R.Loaded.StatValues = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Stat = o
				rel.R.Loaded.Stat = true
			}
		}
		return nil
	case "Definition":
		rel, ok := retrieved.(*Definition)
		if !ok {
			return fmt.Errorf("stat cannot load %T as %q", retrieved, name)
		}

		o.R.Definition = rel
		o.R.Loaded.Definition = true

		if rel != nil {
			rel.R.Stats = StatSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("stat has no relationship %q", name)
	}
}

type statPreloader struct {
	Definition func(...psql.PreloadOption) psql.Preloader
}

func buildStatPreloader() statPreloader {
	return statPreloader{
		Definition: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Definition, DefinitionSlice](psql.PreloadRel{
				Name: "Definition",
				Sides: []psql.PreloadSide{
					{
						From:        Stats,
						To:          Definitions,
						FromColumns: []string{"definition_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Definitions.Columns.Names(), definitionScanMapperNullable, opts...)
		},
	}
}

type statThenLoader[Q orm.Loadable] struct {
	DefinitionVersions func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	StatRecords        func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	StatValues         func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Definition         func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildStatThenLoader[Q orm.Loadable]() statThenLoader[Q] {
	type DefinitionVersionsLoadInterface interface {
		LoadDefinitionVersions(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type StatRecordsLoadInterface interface {
		LoadStatRecords(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type StatValuesLoadInterface interface {
		LoadStatValues(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type DefinitionLoadInterface interface {
		LoadDefinition(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return statThenLoader[Q]{
		DefinitionVersions: thenLoadBuilder[Q](
			"DefinitionVersions",
			func(ctx context.Context, exec bob.Executor, retrieved DefinitionVersionsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadDefinitionVersions(ctx, exec, mods...)
			},
		),
		StatRecords: thenLoadBuilder[Q](
			"StatRecords",
			func(ctx context.Context, exec bob.Executor, retrieved StatRecordsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadStatRecords(ctx, exec, mods...)
			},
		),
		StatValues: thenLoadBuilder[Q](
			"StatValues",
			func(ctx context.Context, exec bob.Executor, retrieved StatValuesLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadStatValues(ctx, exec, mods...)
			},
		),
		Definition: thenLoadBuilder[Q](
			"Definition",
			func(ctx context.Context, exec bob.Executor, retrieved DefinitionLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadDefinition(ctx, exec, mods...)
			},
		),
	}
}

// LoadDefinitionVersions loads the stat's DefinitionVersions into the .R struct
func (o *Stat) LoadDefinitionVersions(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.DefinitionVersions = nil
	o.R.Loaded.DefinitionVersions = false

	related, err := o.DefinitionVersions(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Stats = StatSlice{o}
	}

	o.R.DefinitionVersions = related
	o.R.Loaded.DefinitionVersions = true
	return nil
}

// LoadDefinitionVersions loads the stat's DefinitionVersions into the .R struct
func (os StatSlice) LoadDefinitionVersions(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	q := os.DefinitionVersions(append(
		mods,
		// since we are changing the columns, the defaults must be added if the
		// original mods did not set any; this runs after the user mods and
		// before the related_* columns below, so it sees exactly what they set
		bob.ModFunc[*dialect.SelectQuery](func(q *dialect.SelectQuery) {
			if len(q.SelectList.Columns) == 0 {
				sm.Columns(DefinitionVersions.Columns).Apply(q)
			}
		}),
		sm.Columns(DefinitionVersionStats.Columns.StatID.As("related_stats.ID")),
	)...)

	IDSlice := make([]int64, 0, len(os))

	mapper := scan.Mod(q.Scanner, func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any, any) error) {
		// Resolve each joined key column name to its index once per query. The
		// previous code scanned by name on every row, which meant a linear column
		// search per row; the columns are added by this loader so they are always
		// present, but an unselected column simply stays unresolved and is skipped.
		IDIdx := -1
		for i, col := range cols {
			switch col {
			case "related_stats.ID":
				IDIdx = i
			}
		}

		return func(row *scan.Row) (any, error) {
				IDSlice = append(IDSlice, *new(int64))
				if IDIdx >= 0 {
					row.ScheduleScanByIndex(IDIdx, &IDSlice[len(IDSlice)-1])
				}

				return nil, nil
			},
			func(any, any) error {
				return nil
			}
	})

	definitionVersions, err := bob.Allx[bob.SliceTransformer[*DefinitionVersion, DefinitionVersionSlice]](ctx, exec, q, mapper)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}
		o.R.DefinitionVersions = nil
		o.R.Loaded.DefinitionVersions = true
	}
	// O(N+M) stitch via a map; child key is the carried slice IDSlice[i] (was O(N*M)).
	statByKey := make(map[int64][]*Stat, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		statByKey[o.ID] = append(statByKey[o.ID], o)
	}

	for i, rel := range definitionVersions {
		owners, ok := statByKey[IDSlice[i]]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.Stats = append(rel.R.Stats, o)

			o.R.DefinitionVersions = append(o.R.DefinitionVersions, rel)

		}
	}

	return nil
}

