// LoadDefinition loads the stat's Definition into the .R struct
func (os StatSlice) LoadDefinition(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	definitions, err := os.Definition(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Definition = nil
		o.R.Loaded.Definition = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	statByKey := make(map[int64][]*Stat, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		statByKey[o.DefinitionID] = append(statByKey[o.DefinitionID], o)
	}

	for _, rel := range definitions {

		owners, ok := statByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Definition != nil {
				continue
			}

			rel.R.Stats = append(rel.R.Stats, o)

			o.R.Definition = rel

		}
	}

	return nil
}

// statC is where relationship counts are stored.
type statC struct {
	DefinitionVersions *int64
	StatRecords        *int64
	StatValues         *int64
}

// PreloadCount sets a count in the C struct by name
func (o *Stat) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "DefinitionVersions":
		o.C.DefinitionVersions = &count
	case "StatRecords":
		o.C.StatRecords = &count
	case "StatValues":
		o.C.StatValues = &count
	}
	return nil
}

type statCountPreloader struct {
	DefinitionVersions func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	StatRecords        func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	StatValues         func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildStatCountPreloader() statCountPreloader {
	return statCountPreloader{
		DefinitionVersions: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Stat]("DefinitionVersions", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Stats.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(DefinitionVersionStats.NameAsExpr()),
					sm.Where(psql.Quote(DefinitionVersionStats.Alias(), "stat_id").EQ(psql.Quote(parent, "id"))),
					sm.InnerJoin(DefinitionVersions.NameAsExpr()).On(
						psql.Quote(DefinitionVersions.Alias(), "id").EQ(psql.Quote(DefinitionVersionStats.Alias(), "definition_version_id")),
					),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		StatRecords: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Stat]("StatRecords", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Stats.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(StatRecords.NameAsExpr()),
					sm.Where(psql.Quote(StatRecords.Alias(), "stat_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		StatValues: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*Stat]("StatValues", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Stats.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(StatValues.NameAsExpr()),
					sm.Where(psql.Quote(StatValues.Alias(), "stat_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

type statCountThenLoader[Q orm.Loadable] struct {
	DefinitionVersions func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	StatRecords        func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	StatValues         func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildStatCountThenLoader[Q orm.Loadable]() statCountThenLoader[Q] {
	type DefinitionVersionsCountInterface interface {
		LoadCountDefinitionVersions(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type StatRecordsCountInterface interface {
		LoadCountStatRecords(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type StatValuesCountInterface interface {
		LoadCountStatValues(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return statCountThenLoader[Q]{
		DefinitionVersions: countThenLoadBuilder[Q](
			"DefinitionVersions",
			func(ctx context.Context, exec bob.Executor, retrieved DefinitionVersionsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountDefinitionVersions(ctx, exec, mods...)
			},
		),
		StatRecords: countThenLoadBuilder[Q](
			"StatRecords",
			func(ctx context.Context, exec bob.Executor, retrieved StatRecordsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountStatRecords(ctx, exec, mods...)
			},
		),
		StatValues: countThenLoadBuilder[Q](
			"StatValues",
			func(ctx context.Context, exec bob.Executor, retrieved StatValuesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountStatValues(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountDefinitionVersions loads the count of DefinitionVersions into the C struct
func (o *Stat) LoadCountDefinitionVersions(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.DefinitionVersions(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.DefinitionVersions = &count
	return nil
}

// LoadCountDefinitionVersions loads the count of DefinitionVersions for a slice in a single batch query
func (os StatSlice) LoadCountDefinitionVersions(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[int64], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "bigint[]"))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    int64
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			DefinitionVersionStats.Columns.StatID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Multi-hop: FROM first join table, JOIN through to final related table
		sm.From(DefinitionVersionStats.NameAsExpr()),
		sm.InnerJoin(DefinitionVersions.NameAsExpr()).On(
			DefinitionVersions.Columns.ID.EQ(DefinitionVersionStats.Columns.DefinitionVersionID),
		),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(DefinitionVersionStats.Columns.StatID.EQ(PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(DefinitionVersionStats.Columns.StatID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[int64]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.DefinitionVersions = &count
	}

	return nil
}

